// ── Funzioni comuni di «Foto pronte» ──
const testo = (v) => (v === null || v === undefined ? '' : String(v)).trim();
const has = (o, k) => Object.prototype.hasOwnProperty.call(o || {}, k);
const corto = (s, n) => { const c = Array.from(String(s ?? '')); return c.length > n ? c.slice(0, n - 1).join('') + '…' : String(s ?? ''); };
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const siNo = (v, seVuoto) => { const t = testo(v).toLowerCase(); if (!t) return seVuoto; return ['si', 'sì', 'yes', 'true', 'vero', '1', 'x', 'ok'].includes(t); };
const lette = (nodo) => $(nodo).all().map((i) => i.json || {}).filter((r) => has(r, 'row_number'));
const normale = (s) => testo(s).toLowerCase().replace(/\s+/g, ' ');
const idDaLink = (voce) => {
  const t = testo(voce);
  const m = t.match(/\/d\/([A-Za-z0-9_-]{10,})/) || t.match(/[?&]id=([A-Za-z0-9_-]{10,})/) || t.match(/\/folders\/([A-Za-z0-9_-]{10,})/);
  if (m) return m[1];
  if (/^[A-Za-z0-9_-]{10,}$/.test(t)) return t;
  return '';
};

// I clienti attivi con la cartella Drive, e l'elenco dei file già usati in qualunque riga del Calendario.
// Un file già in una riga non si tocca mai: la riga punta a lui per id.
const cfg = $('Config').first().json;
const solo = testo(cfg.SOLO_CLIENTE);
const righe = lette('Leggi Calendario');
if (!righe.length) throw new Error('Foto pronte ferma: il Calendario è vuoto o non si legge. Senza sapere quali file sono già usati non tocco niente.');
const clienti = $('Leggi Clienti').all().map((i) => i.json || {}).filter((c) => testo(c.cliente));
const visti = new Set();
const uscita = [];
for (const c of clienti) {
  const chiave = testo(c.cliente);
  if (visti.has(chiave)) continue; // il 01 prende la prima riga
  visti.add(chiave);
  if (solo ? chiave !== solo : !siNo(c.attivo, false)) continue;
  const cartella = idDaLink(c.cartella_drive);
  if (!cartella) continue;
  uscita.push({ json: { cliente: chiave, cartella_id: cartella,
    query: `'${cartella}' in parents and mimeType = 'application/vnd.google-apps.folder' and trashed = false` } });
}
return uscita;

