// Per ogni cliente, la cartella «Da programmare» (figlia diretta della cartella del cliente). Le risposte di Drive
// arrivano nello stesso ordine dei clienti. Senza la cartella, il cliente si salta.
const clienti = $('Cartelle dei clienti').all().map((i) => i.json);
const risposte = $('Cartelle del cliente').all().map((i) => i.json || {});
if (clienti.length && risposte.every((r) => r.error || !Array.isArray(r.files))) {
  throw new Error('Foto pronte ferma: Drive non risponde su nessuna cartella dei clienti (credenziale Drive da ricollegare?).');
}
// stessa regola del 05: nome esatto senza maiuscole, e con due cartelle uguali la prima per id
const nome = testo($('Config').first().json.CARTELLA_MODULO) || 'Da programmare';
const uscita = [];
clienti.forEach((c, i) => {
  const r = risposte[i] || {};
  if (r.error || !Array.isArray(r.files)) return;
  const dp = r.files.filter((f) => testo(f.name).toLowerCase() === nome.toLowerCase() && /^[A-Za-z0-9_-]{10,}$/.test(String(f.id || '')))
    .sort((a, b) => String(a.id).localeCompare(String(b.id)))[0];
  if (!dp) return;
  uscita.push({ json: { cliente: c.cliente, dp_id: dp.id, query: `'${dp.id}' in parents and trashed = false` } });
});
return uscita;

