// Decide quali foto sistemare: JPEG o PNG in «Da programmare», non usate in nessuna riga del Calendario, non già
// copie «_ig», e troppo pesanti, fuori dalle proporzioni di Instagram (da 4:5 a 1,91:1) oppure PNG (il 01 vuole JPEG).
// Per ognuna calcola le misure della copia: dentro 1440×1800, mai ingrandita, e i bordi per arrivare alla proporzione.
const cfg = $('Config').first().json;
// interruttore: finché MODALITA non è «vero» non si scarica, non si carica e non si sposta niente: solo il riepilogo
const prova = testo(cfg.MODALITA).toLowerCase() !== 'vero';
const MAX_FOTO = Math.max(1, Number(cfg.MAX_FOTO_PER_NOTTE) || 20);
const MAX_BYTE = (Number(cfg.MB_MASSIMI) || 8) * 1048576;
const LMAX = Number(cfg.LARGHEZZA_MAX) || 1440;
const HMAX = Number(cfg.ALTEZZA_MAX) || 1800;
const RMIN = 0.8;
const RMAX = 1.91;
const usati = new Set();
for (const r of lette('Leggi Calendario')) for (const c of [r.media, r.copertina]) for (const v of testo(c).split('|')) { const id = idDaLink(v); if (id) usati.add(id); }
const posti = $('Da programmare').all().map((i) => i.json);
const risposte = $('Elenca Da programmare').all().map((i) => i.json || {});
if (posti.length && risposte.every((r) => r.error)) throw new Error('Foto pronte ferma: Drive non risponde su nessuna cartella (credenziale da ricollegare?).');
const formato = (f) => {
  const mime = testo(f.mimeType).toLowerCase();
  if (mime === 'image/jpeg' || mime === 'image/jpg' || mime === 'image/pjpeg') return 'jpeg';
  if (mime === 'image/png') return 'png';
  if (mime === '' || mime === 'application/octet-stream') { const e = testo(f.name).toLowerCase().split('.').pop(); return e === 'jpg' || e === 'jpeg' ? 'jpeg' : e === 'png' ? 'png' : ''; }
  return '';
};
const base = (nome) => testo(nome).replace(/\.(?:jpe?g|png)$/i, '');
const pari = (n) => Math.max(0, Math.round(n));
const previsti = new Set();
const uscita = [];
// si comincia ogni notte da un cliente diverso, così nessuno resta sempre in fondo alla fila
const giorno = Math.floor(Date.now() / 86400000);
const ordine = posti.map((p, i) => i);
const inizio = posti.length ? giorno % posti.length : 0;
ordine.push(...ordine.splice(0, inizio));
ordine.forEach((i) => {
  const p = posti[i];
  const r = risposte[i] || {};
  if (r.error || !Array.isArray(r.files)) return;
  const nomi = new Set(r.files.map((f) => normale(f.name)));
  // le copie fatte da questo flusso portano l'id dell'originale (appProperties.origine_ig): così una foto nuova con
  // lo stesso nome non viene scambiata per una già sistemata
  const copiaDi = new Set(r.files.map((f) => (f.appProperties || {}).origine_ig).filter(Boolean));
  const copie = new Set(r.files.filter((f) => (f.appProperties || {}).origine_ig).map((f) => f.id));
  const foto = r.files.filter((f) => formato(f)).sort((a, b) => testo(a.name).localeCompare(testo(b.name)));
  for (const f of foto) {
    if (uscita.length >= MAX_FOTO) break;
    if (usati.has(f.id) || copie.has(f.id) || /_ig$/i.test(base(f.name))) continue;
    const im = f.imageMediaMetadata || {};
    let w = Number(im.width) || 0;
    let h = Number(im.height) || 0;
    if (!w || !h) continue; // misure non lette: la si lascia com'è
    const rot = Number(im.rotation) || 0;
    if (rot === 1 || rot === 3) [w, h] = [h, w]; // foto dell'iPhone salvata girata: la copia esce dritta
    const peso = Number(f.size) || 0;
    const rapporto = w / h;
    const pesante = peso > MAX_BYTE;
    const fuori = rapporto < RMIN - 0.001 || rapporto > RMAX + 0.001;
    const png = formato(f) === 'png';
    if (!pesante && !fuori && !png) continue;
    // contenuto ridotto e bordi: la foto resta intera, i bordi completano la proporzione
    let cw; let ch; let fw; let fh;
    let bordoW = 0;
    let bordoH = 0;
    if (rapporto < RMIN) {
      ch = Math.min(h, HMAX);
      do { cw = Math.max(1, pari(ch * rapporto)); bordoW = Math.max(0, Math.ceil((ch * RMIN - cw) / 2)); if (cw + 2 * bordoW > LMAX) ch -= 2; else break; } while (ch > 10);
    } else if (rapporto > RMAX) {
      cw = Math.min(w, LMAX); ch = Math.max(1, pari(cw / rapporto)); bordoH = Math.max(0, Math.ceil((cw / RMAX - ch) / 2));
    } else { const s = Math.min(1, LMAX / w, HMAX / h); cw = pari(w * s); ch = pari(h * s); }
    fw = cw + 2 * bordoW;
    fh = ch + 2 * bordoH;
    // nome unico: se c'è già un file con quel nome (o un'altra copia di stanotte), si aggiunge un pezzo dell'id
    let nuovo = `${base(f.name)}_ig.jpg`;
    const giaCopia = copiaDi.has(f.id);
    if (!giaCopia && (nomi.has(normale(nuovo)) || previsti.has(normale(nuovo)))) nuovo = `${base(f.name)}_${f.id.slice(-4)}_ig.jpg`;
    previsti.add(normale(nuovo));
    const motivi = [pesante ? `${(peso / 1048576).toFixed(1).replace('.', ',')} MB` : '', fuori ? `${w}×${h}` : '', png ? 'PNG' : ''].filter(Boolean).join(', ');
    uscita.push({ json: { cliente: p.cliente, dp_id: p.dp_id, file_id: f.id, nome: testo(f.name), nuovo_nome: nuovo,
      prova, copia_esiste: giaCopia, larghezza: cw, altezza: ch, tela_w: fw, tela_h: fh, bordo_w: bordoW, bordo_h: bordoH, motivi } });
  }
});
return uscita;

