  if (prove.length) { righe.push(`<b>${esc(corto(cliente, 60))}</b>: avrei sistemato ${prove.length} foto\n${prove.slice(0, 15).map((e) => `• ${esc(corto(e.nome, 50))} → ${esc(corto(e.nuovo_nome, 50))} (${esc(e.motivi)})`).join('\n')}`); continue; }
  righe.push(`<b>${esc(corto(cliente, 60))}</b>: ${fatte.length + mezze.length} copie pronte in «Da programmare»`
    + (fatte.length ? `\n${fatte.slice(0, 10).map((e) => `• ${esc(corto(e.nuovo_nome, 50))} (era ${esc(e.motivi)})`).join('\n')}` : ''));
  if (mezze.length) righe.push(`⚠️ ${mezze.length} copie fatte ma l'originale è rimasto accanto: spostalo a mano in «Originali», altrimenti il modulo propone tutte e due.`);
  if (errori.length) righe.push(`⚠️ ${errori.length} foto non sistemate (${esc([...new Set(errori.map((e) => e.passo))].join(', '))}): gli originali restano dove sono, riprovo la notte dopo.`
    + (errori.some((e) => e.passo === 'caricamento') ? ' Se in «Da programmare» vedi già una copia «_ig» di quella foto, cancellala: potrebbe essere rimasta a metà.' : ''));
}
if (clientiLetti < clientiGuardati) righe.push(`⚠️ ${clientiGuardati - clientiLetti} clienti saltati: Drive non ha risposto o manca la cartella «Da programmare».`);
let t = righe.join('\n\n');
if (t.length > 3900) t = t.slice(0, 3890).slice(0, t.slice(0, 3890).lastIndexOf('\n')) + '\n…';
return [{ json: { testo: t } }];
